namespace RoadRegistry.BackOffice.ZipArchiveWriters.Tests.BackOffice.FeatureCompare.Inwinning.Scenarios;

using System.IO.Compression;
using System.Text;
using FluentAssertions;
using Microsoft.Extensions.Logging;
using RoadRegistry.Extracts.FeatureCompare.Inwinning;
using RoadRegistry.Extracts.Uploads;
using RoadRegistry.Tests.BackOffice.Extracts.Inwinning;
using Xunit.Abstractions;

// A record the dbase reader cannot read stops it where it stands: every record behind it is never seen. The extract
// is generated by the system, so its record problems do not fail an upload - but a read that stopped halfway is not
// a record problem, it is a file the upload cannot be judged against. Swallowed, the feature compare works from an
// extract it believes is complete: a road segment it never read is never matched and never removed, and an upload
// that redraws one of them adds its road next to the one that stayed behind.
public class UnreadableExtractRecordScenarios : FeatureCompareTranslatorScenariosBase
{
    private const string ExtractRoadSegmentsDbaseFileName = "eWegsegment.dbf";

    public UnreadableExtractRecordScenarios(ITestOutputHelper testOutputHelper, ILogger<ZipArchiveFeatureCompareTranslator> logger)
        : base(testOutputHelper, logger)
    {
    }

    [Fact]
    public async Task WhenTheExtractHasARecordThatCannotBeRead_ThenItIsReported()
    {
        var archiveStream = BuildArchiveWithAnUnreadableExtractRoadSegment();

        using var archive = new ZipArchive(archiveStream, ZipArchiveMode.Read, true);
        var sut = ZipArchiveFeatureCompareTranslatorV3Builder.Create();

        var act = () => sut.TranslateAsync(archive, ZipArchiveMetadata.Empty, CancellationToken.None);

        var exception = await act.Should().ThrowAsync<ZipArchiveValidationException>();
        exception.Which.Problems.Select(x => x.Reason).Should()
            .Contain(nameof(DbaseFileProblems.HasDbaseRecordFormatError));
    }

    private static MemoryStream BuildArchiveWithAnUnreadableExtractRoadSegment()
    {
        // The road numbers and the crossings are left out of the extract on purpose: an extract feature pointing at
        // a road segment that is no longer there is reported in its own right, and that is not what is under test.
        var archiveStream = new InwinningZipArchiveBuilder()
            .WithExtract((builder, _) =>
            {
                builder.DataSet.EuropeanRoadDbaseRecords.Clear();
                builder.DataSet.NationalRoadDbaseRecords.Clear();
                builder.DataSet.GradeSeparatedJunctionDbaseRecords.Clear();
            })
            .BuildArchiveStream();

        MakeLastExtractRoadSegmentUnreadable(archiveStream);

        return archiveStream;
    }

    // Writes a date the dbase reader refuses into the CREATIE of the extract's last road segment. The field is
    // written the way it is read - 'yyyyMMdd\THHmmss' - and an ISO date is what a record copied out of the published
    // product carries, which is how such a record ends up in an extract in the first place.
    private static void MakeLastExtractRoadSegmentUnreadable(MemoryStream archiveStream)
    {
        using (var archive = new ZipArchive(archiveStream, ZipArchiveMode.Update, true))
        {
            var entry = archive.Entries.SingleOrDefault(x =>
                string.Equals(x.FullName, ExtractRoadSegmentsDbaseFileName, StringComparison.OrdinalIgnoreCase));
            entry.Should().NotBeNull($"the archive is expected to hold a '{ExtractRoadSegmentsDbaseFileName}'");

            byte[] dbase;
            using (var entryStream = entry!.Open())
            using (var buffer = new MemoryStream())
            {
                entryStream.CopyTo(buffer);
                dbase = buffer.ToArray();
            }

            OverwriteFieldOfLastRecord(dbase, "CREATIE", "2026-11-09");

            using (var entryStream = entry.Open())
            {
                entryStream.SetLength(0);
                entryStream.Write(dbase, 0, dbase.Length);
            }
        }

        archiveStream.Position = 0;
    }

    private static void OverwriteFieldOfLastRecord(byte[] dbase, string fieldName, string value)
    {
        var recordCount = BitConverter.ToInt32(dbase, 4);
        var headerLength = BitConverter.ToUInt16(dbase, 8);
        var recordLength = BitConverter.ToUInt16(dbase, 10);

        recordCount.Should().BeGreaterThan(1, "the extract is expected to hold more than one road segment");

        // The field descriptors follow the 32-byte header, 32 bytes each, up to the 0x0D that closes them off. Each
        // one names its field in its first 11 bytes and gives its length at offset 16; the fields sit in the record
        // in that same order, behind the one byte that marks the record as deleted or not.
        var fieldOffsetInRecord = 1;
        var descriptorOffset = 32;
        while (dbase[descriptorOffset] != 0x0D)
        {
            var name = Encoding.ASCII.GetString(dbase, descriptorOffset, 11).TrimEnd('\0');
            var fieldLength = dbase[descriptorOffset + 16];

            if (name == fieldName)
            {
                var recordOffset = headerLength + (recordCount - 1) * recordLength;
                var written = Encoding.ASCII.GetBytes(value.PadRight(fieldLength));
                Array.Copy(written, 0, dbase, recordOffset + fieldOffsetInRecord, fieldLength);
                return;
            }

            fieldOffsetInRecord += fieldLength;
            descriptorOffset += 32;
        }

        throw new InvalidOperationException($"Field '{fieldName}' was not found in the dbase file.");
    }
}
